    val QUICK_STAPLES: List<BazaarCommodity> by lazy {
        ALL_COMMODITIES.filter { it.isStaple }
    }

    /**
     * Searches commodities based on query supporting:
     * - Bengali exact, word-level, and prefix match
     * - English & Banglish transliterations and aliases
     * - Normalized search fallback
     */
    fun search(query: String, limit: Int = 8): List<BazaarCommodity> {
        val q = query.trim().lowercase()
        if (q.isBlank()) return emptyList()

        val cleanQuery = UnitConverterEngine.normalizeProductName(q)

        return ALL_COMMODITIES.asSequence()
            .map { item ->
                val score = calculateMatchScore(item, q, cleanQuery)
                Pair(item, score)
            }
            .filter { it.second > 0 }
            .sortedWith(
                compareByDescending<Pair<BazaarCommodity, Int>> { it.second }
                    .thenByDescending { it.first.isStaple }
                    .thenBy { it.first.name.length }
            )
            .take(limit)
            .map { it.first }
            .toList()
    }

    private fun calculateMatchScore(item: BazaarCommodity, q: String, cleanQuery: String): Int {
        val nameLower = item.name.lowercase()
        val norm = UnitConverterEngine.normalizeProductName(item.name)

        // 1. Exact match in name or exact transliteration alias
        if (nameLower == q || norm == cleanQuery) return 100
        if (item.aliases.any { it.equals(q, ignoreCase = true) }) return 95

        // 2. Word boundary match in product name (e.g. "আলু" in "নতুন আলু" or "ডিম" in "হাঁসের ডিম")
        val cleanName = nameLower.replace("(", " ").replace(")", " ").replace("/", " ").replace("-", " ")
        val words = cleanName.split(Regex("\\s+")).filter { it.isNotBlank() }
        if (words.contains(q) || words.contains(cleanQuery)) return 90
        if (words.any { it.startsWith(q) || (cleanQuery.isNotBlank() && it.startsWith(cleanQuery)) }) return 80

        // 3. Word boundary match in aliases (e.g. "oil" in "mustard oil", "dim" in "farm egg")
        for (alias in item.aliases) {
            val aliasClean = alias.lowercase().replace("-", " ").replace("/", " ")
            val aliasWords = aliasClean.split(Regex("\\s+")).filter { it.isNotBlank() }
            if (aliasWords.contains(q)) return 85
            if (q.length >= 2 && aliasWords.any { it.startsWith(q) }) return 75
        }

        // 4. Starts with in full name
        if (nameLower.startsWith(q) || norm.startsWith(cleanQuery)) return 70

        // 5. Substring in name if query is at least 3 chars
        if (q.length >= 3 && (nameLower.contains(q) || norm.contains(cleanQuery))) return 50

        return 0
    }
